/// Get a country by its ISO code.
pub fn get_country(code: &str) -> Option<&'static CountryData> {
    COUNTRIES.iter().find(|c| c.code == code)
}

/// Get all countries in a region.
pub fn get_countries_by_region(region: &str) -> Vec<&'static CountryData> {
    COUNTRIES.iter().filter(|c| c.region == region).collect()
}

/// Get all country codes.
pub fn get_all_codes() -> Vec<&'static str> {
    COUNTRIES.iter().map(|c| c.code).collect()
}
